=== FILE: tb_mac8.v ===
// Self-checking scoreboard testbench for mac8.
// Reference model written from interface_spec.md (MAC-RESET, MAC-CLEAR,
// MAC-ACC, MAC-HOLD, MAC-SAT, MAC-STICKY), not from the RTL.
`timescale 1ns / 1ps
module tb_mac8;
    reg         clk;
    reg         rst_n, clr, en;
    reg  [7:0]  a, b;
    wire [23:0] acc;
    wire        sat;

    mac8 dut (
        .clk(clk), .rst_n(rst_n), .clr(clr), .en(en),
        .a(a), .b(b), .acc(acc), .sat(sat)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Reference model state
    reg [23:0] m_acc;
    reg        m_sat;
    reg [31:0] m_sum;

    // Scoreboard bookkeeping
    integer pass_cnt, fail_cnt, cycle;
    integer n_sat_event, n_exact_max, n_clr_en, n_clr_only, n_hold, n_rst_en,
            n_rst_clr, n_sticky, n_unsigned, n_sat_hold;
    integer sat_before_random;
    integer seed, i, k, rnd;
    reg [7:0] r_a, r_b;
    reg       r_rst, r_clr, r_en;
    reg [8*128-1:0] nonce;
    reg [7:0]  ch;
    reg        got_nonce;

    // Model of one rising edge, from the specification.
    task model_edge;
        input       r, c, e;
        input [7:0] x, y;
        begin
            if (!r) begin
                if (e) n_rst_en = n_rst_en + 1;
                if (c) n_rst_clr = n_rst_clr + 1;
                m_acc = 24'd0;
                m_sat = 1'b0;
            end else if (c) begin
                if (e) n_clr_en = n_clr_en + 1;
                else   n_clr_only = n_clr_only + 1;
                m_acc = 24'd0;
                m_sat = 1'b0;
            end else if (e) begin
                if (m_sat) n_sticky = n_sticky + 1;
                if ((x[7] && y != 8'd0) || (y[7] && x != 8'd0))
                    n_unsigned = n_unsigned + 1;
                m_sum = {8'd0, m_acc} + ({24'd0, x} * {24'd0, y});
                if (m_sum == 32'h00FFFFFF) n_exact_max = n_exact_max + 1;
                if (m_sum > 32'h00FFFFFF) begin
                    n_sat_event = n_sat_event + 1;
                    m_acc = 24'hFFFFFF;
                    m_sat = 1'b1;
                end else begin
                    m_acc = m_sum[23:0];
                end
            end else begin
                n_hold = n_hold + 1;
                if (m_sat) n_sat_hold = n_sat_hold + 1;
            end
        end
    endtask

    task check_outputs;
        input       r, c, e;
        input [7:0] x, y;
        begin
            if (acc === m_acc) pass_cnt = pass_cnt + 1;
            else begin
                fail_cnt = fail_cnt + 1;
                if (fail_cnt <= 20)
                    $display("MISMATCH acc cycle=%0d rst_n=%b clr=%b en=%b a=%0d b=%0d dut_acc=%h model_acc=%h dut_sat=%b model_sat=%b",
                             cycle, r, c, e, x, y, acc, m_acc, sat, m_sat);
            end
            if (sat === m_sat) pass_cnt = pass_cnt + 1;
            else begin
                fail_cnt = fail_cnt + 1;
                if (fail_cnt <= 20)
                    $display("MISMATCH sat cycle=%0d rst_n=%b clr=%b en=%b a=%0d b=%0d dut_acc=%h model_acc=%h dut_sat=%b model_sat=%b",
                             cycle, r, c, e, x, y, acc, m_acc, sat, m_sat);
            end
        end
    endtask

    // Drive inputs away from the edge, let the edge happen, update the model,
    // then sample the DUT after it has settled.
    task step;
        input       r, c, e;
        input [7:0] x, y;
        begin
            rst_n = r; clr = c; en = e; a = x; b = y;
            @(posedge clk);
            model_edge(r, c, e, x, y);
            cycle = cycle + 1;
            #1;
            check_outputs(r, c, e, x, y);
        end
    endtask

    task corner_required;
        input integer count;
        input [8*24-1:0] name;
        begin
            if (count == 0) begin
                fail_cnt = fail_cnt + 1;
                $display("CORNER NOT REACHED: %0s", name);
            end else begin
                $display("corner %0s reached %0d times", name, count);
            end
        end
    endtask

    initial begin
        pass_cnt = 0; fail_cnt = 0; cycle = 0;
        n_sat_event = 0; n_exact_max = 0; n_clr_en = 0; n_clr_only = 0;
        n_hold = 0; n_rst_en = 0; n_rst_clr = 0; n_sticky = 0;
        n_unsigned = 0; n_sat_hold = 0;
        seed = 32'h1F2E3D4C;
        m_acc = 24'd0; m_sat = 1'b0; m_sum = 32'd0;
        rst_n = 1'b0; clr = 1'b0; en = 1'b0; a = 8'd0; b = 8'd0;

        nonce = 0; got_nonce = 1'b0;
        if ($value$plusargs("NIRMAAN_NONCE=%s", nonce)) got_nonce = 1'b1;
        else if ($value$plusargs("nirmaan_nonce=%s", nonce)) got_nonce = 1'b1;
        else if ($value$plusargs("nonce=%s", nonce)) got_nonce = 1'b1;
        else if ($value$plusargs("NONCE=%s", nonce)) got_nonce = 1'b1;
        if (!got_nonce) $display("WARNING: no nonce plusarg found");

        // MAC-RESET: reset wins over an offered accumulate, and over clr.
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b1, 1'b1, 8'h12, 8'h34);

        // MAC-HOLD right after reset with nonzero operands.
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);

        // MAC-ACC: simple accumulation.
        step(1'b1, 1'b0, 1'b1, 8'd3, 8'd4);
        step(1'b1, 1'b0, 1'b1, 8'd10, 8'd20);
        step(1'b1, 1'b0, 1'b1, 8'd0, 8'd255);
        step(1'b1, 1'b0, 1'b1, 8'd255, 8'd0);

        // MAC-HOLD: en low, operands change.
        step(1'b1, 1'b0, 1'b0, 8'hAA, 8'h55);
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'h01);
        step(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);

        // Unsigned reading of operands (signed would differ).
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'h01);
        step(1'b1, 1'b0, 1'b1, 8'h01, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h80, 8'h80);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'h7F);
        step(1'b1, 1'b0, 1'b1, 8'h81, 8'hFE);

        // MAC-CLEAR: clear wins over an accumulate at the same edge.
        step(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'd7, 8'd9);
        step(1'b1, 1'b1, 1'b0, 8'd7, 8'd9);

        // MAC-SAT boundary: land exactly on 0xFFFFFF without saturating.
        step(1'b1, 1'b1, 1'b0, 8'd0, 8'd0);
        for (i = 0; i < 258; i = i + 1)
            step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'h03);   // exactly 0xFFFFFF, sat stays 0
        step(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);   // sum still 0xFFFFFF, no sat
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);   // hold
        step(1'b1, 1'b0, 1'b1, 8'h01, 8'h01);   // one over: saturate

        // MAC-STICKY: flag stays through accumulate and hold.
        step(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b0, 8'h10, 8'h10);
        step(1'b1, 1'b0, 1'b1, 8'h01, 8'h02);
        step(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);

        // Clear while saturated, then small accumulates keep sat low.
        step(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'd2, 8'd3);
        step(1'b1, 1'b0, 1'b1, 8'd200, 8'd100);

        // Minimal overshoot from below max (wrap would give a small value).
        step(1'b1, 1'b1, 1'b0, 8'd0, 8'd0);
        for (i = 0; i < 258; i = i + 1)
            step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'h04);   // 0xFFFFFF + 255
        step(1'b1, 1'b0, 1'b1, 8'h00, 8'h01);

        // Large overshoot from near max.
        step(1'b1, 1'b1, 1'b0, 8'd0, 8'd0);
        for (i = 0; i < 258; i = i + 1)
            step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);   // far beyond max

        // Reset in the middle of operation while saturated, with en high.
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'd5, 8'd5);
        step(1'b1, 1'b0, 1'b0, 8'd5, 8'd5);

        // Seeded random phase.
        sat_before_random = n_sat_event;
        for (i = 0; i < 6000; i = i + 1) begin
            rnd = {$random(seed)} % 2048;
            r_rst = (rnd < 2) ? 1'b0 : 1'b1;
            r_clr = (rnd >= 2 && rnd < 5) ? 1'b1 : 1'b0;
            rnd = {$random(seed)} % 10;
            r_en = (rnd < 8) ? 1'b1 : 1'b0;
            rnd = $random(seed);
            if (({$random(seed)} % 4) != 0) r_a = 8'hC0 | rnd[7:0];
            else                            r_a = rnd[7:0];
            rnd = $random(seed);
            if (({$random(seed)} % 4) != 0) r_b = 8'hC0 | rnd[7:0];
            else                            r_b = rnd[7:0];
            step(r_rst, r_clr, r_en, r_a, r_b);
        end
        $display("random phase saturation events: %0d", n_sat_event - sat_before_random);

        // The run must have reached every specified corner.
        corner_required(n_rst_en,    "reset_with_en");
        corner_required(n_rst_clr,   "reset_with_clr");
        corner_required(n_clr_en,    "clear_with_en");
        corner_required(n_clr_only,  "clear_without_en");
        corner_required(n_hold,      "hold_en_low");
        corner_required(n_unsigned,  "unsigned_operands");
        corner_required(n_exact_max, "exact_max_no_sat");
        corner_required(n_sat_event, "saturation");
        corner_required(n_sticky,    "sticky_accumulate");
        corner_required(n_sat_hold,  "sticky_hold");

        $write("NIRMAAN-SIM ");
        for (k = 127; k >= 0; k = k - 1) begin
            ch = nonce[k*8 +: 8];
            if (ch != 8'd0) $write("%c", ch);
        end
        $display(" %0d passed, %0d failed", pass_cnt, fail_cnt);
        $finish;
    end
endmodule
=== END FILE ===
